#include <stdio.h>

struct Student {
    char name[10];
    int score[3];
};

int dec(int n) {
    return (n >> 4) + (n & 0x0F);
}

int sum(struct Student* p) {
    return dec(p->score[0]) + dec(p->score[1]) + dec(p->score[2]);
}

